export default function SuccessPage() {
  const navigate = useNavigate();
  const { orderNumber, totalPrice, buyerFirstName, buyerPatronymic } =
    useBooking();
  const [rating, setRating] = useState(0);
  const [hovered, setHovered] = useState(0);


  const greeting = buyerFirstName
    ? `${buyerFirstName}${buyerPatronymic ? " " + buyerPatronymic : ""}!`
    : "Спасибо за заказ!";

  return (
    <div
      style={{ fontFamily: "'Roboto', sans-serif" }}
      className="min-h-screen bg-white"
    >
      
      <div
        className="relative w-full bg-cover bg-center"
        style={{ backgroundImage: `url(public/images/station-background.png)` }}
      >
        <div className="absolute inset-0 bg-gradient-to-b from-black/30 via-black/40 to-[#c47a00]/60 pointer-events-none" />

        <div className="relative z-10">
          <Header />
        </div>

        <section className="relative z-10 min-h-[340px] flex items-end pb-24">
          <div className="max-w-3xl mx-auto px-6 w-full">
            <h1 className="text-white text-3xl md:text-4xl font-black mb-0 drop-shadow-lg">
              Благодарим Вас за заказ!
            </h1>
          </div>
        </section>
      </div>
      

      
      <div className="max-w-3xl mx-auto px-6 relative z-10 -mt-20">
        <div className="bg-white shadow-lg border border-gray-100">
          
          <div className="flex items-center justify-between px-8 py-5 border-b border-gray-100">
            <h2 className="text-base font-bold text-gray-800">
              №Заказа <span className="text-gray-900">{orderNumber}</span>
            </h2>
            <div className="text-sm text-gray-500">
              сумма{" "}
              <span className="text-gray-900 font-bold ml-1">
                {totalPrice.toLocaleString()} ₽
              </span>
            </div>
          </div>

          
          <div className="flex justify-center gap-16 px-8 py-8 bg-gray-50 border-b border-gray-100">
            {STEPS_INFO.map((s, i) => (
              <div
                key={i}
                className="flex flex-col items-center text-center gap-3 w-36"
              >
                {s.icon}
                <p className="text-xs text-gray-500 leading-snug whitespace-pre-line">
                  {s.label}
                </p>
              </div>
            ))}
          </div>

          
          <div className="px-8 py-8 border-b border-gray-100">
            <p className="text-lg font-bold text-gray-900 mb-3">{greeting}</p>
            <p className="text-sm text-gray-600 leading-relaxed mb-4">
              Ваш заказ успешно оформлен.
              <br />В ближайшее время с вами свяжется наш оператор для
              подтверждения.
            </p>
            <p className="text-sm font-bold text-gray-800">
              Благодарим Вас за оказанное доверие и желаем приятного
              путешествия!
            </p>
          </div>

         
          <div className="flex items-center justify-between px-8 py-5 bg-[#f5a623]">
            <div className="flex items-center gap-3">
              <span className="text-black/70 text-sm font-medium">
                Оценить сервис
              </span>
              <div className="flex gap-1">
                {[1, 2, 3, 4, 5].map((star) => (
                  <button
                    key={star}
                    onMouseEnter={() => setHovered(star)}
                    onMouseLeave={() => setHovered(0)}
                    onClick={() => setRating(star)}
                    className="transition-transform hover:scale-110"
                  >
                    <svg
                      className={`w-7 h-7 transition-colors ${(hovered || rating) >= star ? "text-white" : "text-black/20"}`}
                      fill="currentColor"
                      viewBox="0 0 24 24"
                    >
                      <path d="M12 2l3.09 6.26L22 9.27l-5 4.87L18.18 21 12 17.77 5.82 21 7 14.14 2 9.27l6.91-1.01L12 2z" />
                    </svg>
                  </button>
                ))}
              </div>
            </div>
            <button
              onClick={() => navigate("/")}
              className="border-2 border-black/30 text-black font-bold text-sm px-6 py-2.5 hover:bg-black/10 transition-colors tracking-wide"
            >
              ВЕРНУТЬСЯ НА ГЛАВНУЮ
            </button>
          </div>
        </div>
      </div>

      <div className="pb-16" />
      <Footer />
    </div>
  );
}
